package com.example.Hospital.Management.System.repositories; import com.example.Hospital.Management.System.entities.Room; import org.springframework.data.jpa.repository.*; import java.util.*; public interface RoomRepository extends JpaRepository<Room,Long>{List<Room> findByIsActiveTrue(); @Query("select r from Room r where r.isActive=true and r.capacity > (select count(a) from Admission a where a.room.id=r.id and a.isActive=true and a.dischargeDate is null)") List<Room> roomsWithCapacity();}
